import { useEffect, useRef, useState } from "react";
import { Volume2, VolumeX } from "lucide-react";

// Картинка стиснута й вбудована (480x480, ~43 КБ base64) — оригінал від
// користувача важив 963 КБ, для мобільного екрану цього більш ніж досить.
const MAINTENANCE_IMAGE = "data:image/jpeg;base64,";

// Звуку від користувача не було надано, тому цокання синтезоване через
// Web Audio (коротка "клацаюча" нота) — легко замінити на реальний файл
// пізніше. Вимкнено за замовчуванням: браузери й так блокують автозвук
// без взаємодії користувача, тож перший тап вмикає звук.
function useTickSound(enabled) {
  const ctxRef = useRef(null);
  const intervalRef = useRef(null);

  useEffect(() => {
    if (!enabled) {
      if (intervalRef.current) clearInterval(intervalRef.current);
      return;
    }
    if (!ctxRef.current) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      ctxRef.current = new AudioCtx();
    }
    const playTick = () => {
      const ctx = ctxRef.current;
      if (!ctx) return;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "square";
      osc.frequency.value = 1200;
      gain.gain.setValueAtTime(0.06, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.04);
      osc.connect(gain).connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.05);
    };
    playTick();
    intervalRef.current = setInterval(playTick, 1000);
    return () => clearInterval(intervalRef.current);
  }, [enabled]);
}

export default function MaintenanceScreen({ message }) {
  const [soundOn, setSoundOn] = useState(false);
  useTickSound(soundOn);

  return (
    <div className="cn-maint-screen">
      <button
        className="cn-maint-sound-btn"
        onClick={() => setSoundOn((v) => !v)}
        aria-label={soundOn ? "Вимкнути звук" : "Увімкнути звук"}
      >
        {soundOn ? <Volume2 size={18} /> : <VolumeX size={18} />}
      </button>

      <div className="cn-maint-card">
        <img src={MAINTENANCE_IMAGE} alt="" className="cn-maint-image" />

        <svg className="cn-maint-clock" viewBox="0 0 100 100" aria-hidden="true">
          <circle cx="50" cy="50" r="46" className="cn-maint-clock-face" />
          {Array.from({ length: 12 }).map((_, i) => (
            <line
              key={i}
              x1="50"
              y1="8"
              x2="50"
              y2="14"
              className="cn-maint-clock-tick"
              transform={`rotate(${i * 30} 50 50)`}
            />
          ))}
          <line x1="50" y1="50" x2="50" y2="26" className="cn-maint-clock-hand cn-maint-clock-hand--minute" />
          <line x1="50" y1="50" x2="50" y2="32" className="cn-maint-clock-hand cn-maint-clock-hand--hour" />
          <circle cx="50" cy="50" r="2.5" className="cn-maint-clock-pin" />
        </svg>

        <h1 className="cn-maint-title">Технічні роботи</h1>
        <p className="cn-maint-body">
          {message || "Ми оновлюємо гру — скоро повернемось. Дякуємо за терпіння!"}
        </p>
      </div>

      <style>{`
        .cn-maint-screen {
          position: fixed;
          inset: 0;
          z-index: 9999;
          display: flex;
          align-items: center;
          justify-content: center;
          background: radial-gradient(circle at 50% 20%, #fbbf6a 0%, #e8871f 55%, #b3480f 100%);
          padding: 24px;
          overflow: hidden;
        }
        .cn-maint-sound-btn {
          position: absolute;
          top: 16px;
          right: 16px;
          width: 40px;
          height: 40px;
          border-radius: 999px;
          border: none;
          background: rgba(0,0,0,0.25);
          color: #fff;
          display: flex;
          align-items: center;
          justify-content: center;
        }
        .cn-maint-card {
          max-width: 360px;
          width: 100%;
          display: flex;
          flex-direction: column;
          align-items: center;
          text-align: center;
          color: #3a1c05;
        }
        .cn-maint-image {
          width: 220px;
          height: 220px;
          object-fit: contain;
          filter: drop-shadow(0 12px 24px rgba(0,0,0,0.25));
          margin-bottom: 4px;
        }
        .cn-maint-clock {
          width: 72px;
          height: 72px;
          margin-bottom: 16px;
        }
        .cn-maint-clock-face {
          fill: rgba(255,255,255,0.85);
          stroke: #3a1c05;
          stroke-width: 2;
        }
        .cn-maint-clock-tick {
          stroke: #3a1c05;
          stroke-width: 2;
        }
        .cn-maint-clock-hand {
          stroke: #3a1c05;
          stroke-width: 3;
          stroke-linecap: round;
          transform-origin: 50px 50px;
        }
        .cn-maint-clock-hand--minute {
          animation: cn-maint-spin 6s linear infinite;
        }
        .cn-maint-clock-hand--hour {
          animation: cn-maint-spin 72s linear infinite;
        }
        .cn-maint-clock-pin {
          fill: #3a1c05;
        }
        @keyframes cn-maint-spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        .cn-maint-title {
          font-size: 22px;
          font-weight: 800;
          margin: 0 0 8px;
        }
        .cn-maint-body {
          font-size: 15px;
          line-height: 1.5;
          margin: 0;
          opacity: 0.9;
        }
      `}</style>
    </div>
  );
}
